package studio.panel;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.zip.*;
public class MainActivity extends Activity {
 Bitmap image; EditText width,height,thick,gap,depth,base; Spinner mode; Preview preview; double W=600,H=400,T=12,G=8,D=45,B=10; int N=30; final int S=100; double angle=.6; boolean invert=false;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,24,16,16);setContentView(root); TextView title=new TextView(this);title.setText("PARAMETRIC PANEL STUDIO");title.setTextSize(22);root.addView(title);preview=new Preview();root.addView(preview,new LinearLayout.LayoutParams(-1,0,1));ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);sc.addView(controls);button(controls,"Import image",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,1);});width=field(controls,"Width mm","600");height=field(controls,"Height mm","400");thick=field(controls,"Rib thickness mm","12");gap=field(controls,"Gap mm","8");depth=field(controls,"Relief depth mm","45");base=field(controls,"Base depth mm","10");CheckBox cb=new CheckBox(this);cb.setText("Invert image");controls.addView(cb);cb.setOnCheckedChangeListener((v,c)->{invert=c;preview.invalidate();});button(controls,"Regenerate",()->{if(read())preview.invalidate();});mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"3-axis router: DXF + STL","5-axis milling: STL + OBJ","Laser cutter: DXF + SVG"}));controls.addView(mode);button(controls,"Export all components ZIP",()->{if(!read())return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"Panel_Components.zip");startActivityForResult(i,2);});}
 void button(LinearLayout l,String s,Runnable r){Button b=new Button(this);b.setText(s);l.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(LinearLayout l,String s,String value){TextView t=new TextView(this);t.setText(s);l.addView(t);EditText e=new EditText(this);e.setInputType(8194);e.setText(value);l.addView(e);return e;}
 boolean read(){try{double w=Double.parseDouble(width.getText().toString()),h=Double.parseDouble(height.getText().toString()),t=Double.parseDouble(thick.getText().toString()),g=Double.parseDouble(gap.getText().toString()),d=Double.parseDouble(depth.getText().toString()),b=Double.parseDouble(base.getText().toString());if(!(w>0&&h>0&&t>0&&g>=0&&d>=0&&b>0&&w<=10000&&h<=10000&&t<=w&&d<=10000&&b<=10000))throw new Exception();int n=(int)Math.floor((w+g)/(t+g));if(n<1||n>300)throw new Exception();W=w;H=h;T=t;G=g;D=d;B=b;N=n;return true;}catch(Exception e){Toast.makeText(this,"Invalid dimensions (1–300 ribs)",0).show();return false;}}
 double z(int i,int j){double u=(i*(T+G)+T/2)/W,v=j/(double)S;double a;if(image==null)a=.5+.5*Math.sin(u*12+v*8);else{int p=image.getPixel(Math.min(image.getWidth()-1,(int)(u*image.getWidth())),Math.min(image.getHeight()-1,(int)((1-v)*image.getHeight())));a=(.2126*Color.red(p)+.7152*Color.green(p)+.0722*Color.blue(p))/255;}return B+D*(invert?1-a:a);}
 double[][] profile(int i){double[][] p=new double[S+3][2];p[0]=new double[]{0,0};for(int j=0;j<=S;j++)p[j+1]=new double[]{z(i,j),H*j/S};p[S+2]=new double[]{0,H};return p;}
 class Preview extends View{Paint p=new Paint(3);float last;Preview(){super(MainActivity.this);}protected void onDraw(Canvas c){c.drawColor(0xff161a20);float scale=(float)Math.min(getWidth()/(W+D+B+20),getHeight()/(H+W*.25+20))*.9f;float ox=getWidth()/2f,oy=getHeight()/2f;for(int k=0;k<N;k++){int i=angle>=0?N-1-k:k;double x=i*(T+G)-W/2;for(int j=0;j<S;j++){double a=z(i,j),b=z(i,j+1);float y=(float)(H/2-H*j/S),yn=(float)(H/2-H*(j+1)/S);Path path=new Path();float xx=(float)(x*Math.cos(angle));path.moveTo(ox+scale*(xx+(float)(a*Math.sin(angle))),oy+scale*y);path.lineTo(ox+scale*(xx+(float)(b*Math.sin(angle))),oy+scale*yn);path.lineTo(ox+scale*(xx+(float)(b*Math.sin(angle)+T*Math.cos(angle))),oy+scale*yn);path.lineTo(ox+scale*(xx+(float)(a*Math.sin(angle)+T*Math.cos(angle))),oy+scale*y);path.close();int shade=(int)Math.max(70,Math.min(230,175+(a-b)*12));p.setColor(Color.rgb(shade,(int)(shade*.78),(int)(shade*.53)));c.drawPath(path,p);}}}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){last=e.getX();return true;}if(e.getAction()==2){angle=Math.max(-1.3,Math.min(1.3,angle+(e.getX()-last)*.005));last=e.getX();invalidate();}return true;}}
 protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;try{if(r==1){BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(data.getData())){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=Math.max(1,Integer.highestOneBit(Math.max(o.outWidth,o.outHeight)/1024));o.inJustDecodeBounds=false;try(InputStream in=getContentResolver().openInputStream(data.getData())){image=BitmapFactory.decodeStream(in,null,o);}preview.invalidate();}else if(r==2){int m=mode.getSelectedItemPosition();try(ZipOutputStream out=new ZipOutputStream(getContentResolver().openOutputStream(data.getData()))){StringBuilder csv=new StringBuilder("Part,Height_mm,Thickness_mm,Max_depth_mm\n");for(int i=0;i<N;i++){String name=String.format(Locale.US,"Rib_%03d",i+1);double[][] p=profile(i);if(m!=1)put(out,name+".dxf",dxf(p));if(m==2)put(out,name+".svg",svg(p));else{put(out,name+".stl",mesh(p,false));if(m==1)put(out,name+".obj",mesh(p,true));}double max=0;for(double[] q:p)max=Math.max(max,q[0]);csv.append(name+","+H+","+T+","+max+"\n");}put(out,"Cutting_List.csv",csv.toString());}Toast.makeText(this,"Export complete",0).show();}}catch(Exception e){Toast.makeText(this,"Error: "+e.getMessage(),1).show();}}
 void put(ZipOutputStream o,String n,String s)throws Exception{o.putNextEntry(new ZipEntry(n));o.write(s.getBytes("UTF-8"));o.closeEntry();}
 String dxf(double[][] p){StringBuilder s=new StringBuilder("0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1015\n9\n$INSUNITS\n70\n4\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n0\nLWPOLYLINE\n100\nAcDbEntity\n8\nCUT\n100\nAcDbPolyline\n90\n"+p.length+"\n70\n1\n");for(double[] q:p)s.append("10\n"+q[0]+"\n20\n"+q[1]+"\n");return s+"0\nENDSEC\n0\nEOF\n";}
 String svg(double[][] p){StringBuilder s=new StringBuilder("<svg xmlns='http://www.w3.org/2000/svg' width='"+(B+D)+"mm' height='"+H+"mm' viewBox='0 0 "+(B+D)+" "+H+"'><polygon fill='none' stroke='black' stroke-width='0.1' points='");for(double[] q:p)s.append(q[0]+","+(H-q[1])+" ");return s+"'/></svg>";}
 String mesh(double[][] p,boolean obj){StringBuilder s=new StringBuilder(obj?"# units mm\n":"solid rib\n");ArrayList<double[]> v=new ArrayList<>();for(int j=0;j<=S;j++){double y=H*j/S,x=p[j+1][0];v.add(new double[]{0,y,0});v.add(new double[]{x,y,0});v.add(new double[]{0,y,T});v.add(new double[]{x,y,T});}if(obj)for(double[] q:v)s.append("v "+q[0]+" "+q[1]+" "+q[2]+"\n");for(int j=0;j<S;j++){int a=j*4,b=a+4;quad(s,v,a,b,b+1,a+1,obj);quad(s,v,a+2,a+3,b+3,b+2,obj);quad(s,v,a,a+2,b+2,b,obj);quad(s,v,a+1,b+1,b+3,a+3,obj);}quad(s,v,0,1,3,2,obj);int a=S*4;quad(s,v,a,a+2,a+3,a+1,obj);if(!obj)s.append("endsolid rib\n");return s.toString();}
 void quad(StringBuilder s,ArrayList<double[]> v,int a,int b,int c,int d,boolean obj){tri(s,v,a,b,c,obj);tri(s,v,a,c,d,obj);}
 void tri(StringBuilder s,ArrayList<double[]> v,int a,int b,int c,boolean obj){if(obj){s.append("f "+(a+1)+" "+(b+1)+" "+(c+1)+"\n");return;}double[] p=v.get(a),q=v.get(b),r=v.get(c);double ux=q[0]-p[0],uy=q[1]-p[1],uz=q[2]-p[2],vx=r[0]-p[0],vy=r[1]-p[1],vz=r[2]-p[2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,l=Math.sqrt(nx*nx+ny*ny+nz*nz);if(l==0)return;s.append("facet normal "+nx/l+" "+ny/l+" "+nz/l+"\nouter loop\n");for(double[] t:new double[][]{p,q,r})s.append("vertex "+t[0]+" "+t[1]+" "+t[2]+"\n");s.append("endloop\nendfacet\n");}
}